def _looks_like_codec_err(text):
    t = (text or "").lower()
    return any(s in t for s in ("codec", "could not find", "invalid data", "does not support",
                                "incompatible", "non-monotonous", "unable to", "no such codec",
                                "failed to", "could not write header"))

